module parity_8bit (
    input [7:0] in,
    output out
);
    assign out = ^in;
endmodule

module parity_8bit (
    input [7:0] in,
    output out
);
    parameter EVEN = 1;

    function [7:0] count_ones;
        input [7:0] in;
        integer i;
        reg [7:0] count;
        begin
            count = 0;
            for (i = 0; i < 8; i = i + 1) begin
                count = count + in[i];
            end
            count_ones = count;
        end
    endfunction

    assign out = (EVEN) ? (~count_ones(in)[7]) : count_ones(in)[7];

endmodule

module parity_8bit (
    input [7:0] in,
    output out
);
    wire [3:0] tens = in[7:4];
    wire [3:0] units = in[3:0];

    // Calculate 10*tens using shifts (8*tens + 2*tens)
    wire [6:0] tens_times_10 = (tens << 3) + (tens << 1);

    // Add 6*units (6 = 4 + 2)
    wire [5:0] units_times_6 = (units << 2) + (units << 1);

    // Final addition
    assign out = tens_times_10 + units_times_6;
endmodule

module parity_8bit (
