    // Parity bit is the XOR of all 8 input bits
    assign out = ^in;
endmodule

module parity_8bit (
    input [7:0] in,
    output out
);

    reg [16:0] shift_reg;
    reg [5:0] counter;

    always @(posedge in[0] or posedge in[7]) begin
        if (in[7]) begin
            shift_reg <= 17'b11111111111111111;
            counter <= 6'b0;
        end else begin
            if (counter == 6'd16) begin
                counter <= 6'b0;
                shift_reg <= {shift_reg[15:0], 1'b1};
            end else begin
                shift_reg <= {shift_reg[15:0], 1'b0};
                counter <= counter + 1;
            end
        end
    end

    assign out = shift_reg[16];

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

    function [3:0] inverse;
        input [1:0] sel;
        begin
            case (sel)
                2'b00: inverse = 4'b1111; // s0: all bits inverted
                2'b01: inverse = 4'b1100; // s1: lower 2 bits inverted
                2'b10: inverse = 4'b1010; // s2: bits 1 and 3 inverted
                2'b11: inverse = 4'b0101; // s3: bits 2 and 3 inverted
                default: inverse = 4'b0000;
            endcase
        end
    endfunction

    assign out = inverse(sel)[in[0]];

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

    (* keep = "true" *) wire [3:0] term0, term1, term2, term3;
    (* keep = "true" *) wire [3:0] and_outs;

    // Generate inverted input signals
    not (in[0], in[3]);
    not (in[1], in[2]);

    // Term0: sel[1]' & in[0] & in[1] & in[2]
    and (term0[0], in[3], in[0], in[2], in[1]);
    nand (term0[1], term0[0], term0[0]);
    and (term0[2], term0[1], term0[1]);
    nand (term0[3], term0[2], term0[2]);

    // Term1: sel[1] & in[0] & in[1] & in[3]
    and (term1[0], in[2], in[0], in[1], in[3]);
    nand (term1[1], term1[0], term1[0]);
    and (term1[2], term1[1], term1[1]);
    nand (term1[3], term1[2], term1[2]);

    // Term2: sel[1] & in[0] & in[2] & in[3]
    and (term2[0], in[2], in[0], in[1], in[3]);
    nand (term2[1], term2[0], term2[0]);
    and (term2[2], term2[1], term2[1]);
    nand (term2[3], term2[2], term2[2]);

    // Term3: sel[1] & in[1] & in[2] & in[3]
    and (term3[0], in[1], in[2], in[3]);
    nand (term3[1], term3[0], term3[0]);
    and (term3[2], term3[1], term3[1]);
    nand (term3[3], term3[2], term3[2]);

    // Combine terms using OR gates
    or (and_outs[0], term0[0], term1[0], term2[0], term3[0]);
    or (and_outs[1], term0[1], term1[1], term2[1], term3[1]);
    or (and_outs[2], term0[2], term1[2], term2[2], term3[2]);
    or (and_outs[3], term0[3], term1[3], term2[3], term3[3]);

    // Invert intermediate results
    not (out, and_outs[0]);
    not (out, and_outs[1]);
    not (out, and_outs[2]);
    not (out, and_outs[3]);
    not (out, out);

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

wire not_sel0, not_sel1;
wire term0, term1, term2, term3;

// Invert select signals
not (not_sel0, sel[0]);
not (not_sel1, sel[1]);

// Generate AND terms for each input
and (term0, in[0], not_sel1, not_sel0);
and (term1, in[1], not_sel1, sel[0]);
and (term2, in[2], sel[1], not_sel0);
and (term3, in[3], sel[1], sel[0]);

// Combine all terms to get output
or (out, term0, term1, term2, term3);

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    wire [3:0] term0, term1, term2, term3;

    assign term0 = in[0] & (sel == 2'b00);
    assign term1 = in[1] & (sel == 2'b01);
    assign term2 = in[2] & (sel == 2'b10);
    assign term3 = in[3] & (sel == 2'b11);

    assign out = term0 | term1 | term2 | term3;
endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    wire en0 = ~sel[1] & ~sel[0];
    wire en1 = ~sel[1] &  sel[0];
    wire en2 =  sel[1] & ~sel[0];
    wire en3 =  sel[1] &  sel[0];

    assign out = (in[0] & en0) | (in[1] & en1) | (in[2] & en2) | (in[3] & en3);
endmodule

