module majority (
    input a, b, c,
    output out
);
    parameter DELAY = 1;
    wire sub1, sub2;

    // Compute sub1 = a & ~b using subtraction
    assign #DELAY sub1 = a - b;

    // Compute sub2 = sub1 & c using subtraction
    assign #DELAY sub2 = sub1 - c;

    // Assign output
    assign out = sub2;
endmodule

