module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);
    wire [3:0] borrow;

    assign borrow[0] = 1'b0;
    assign equal[0] = (a[0] == b[0]);

    genvar i;
    generate
        for (i = 1; i < 4; i = i + 1) begin : gen_loop
            assign borrow[i] = borrow[i-1] & (b[i] != a[i]);
            assign equal[i] = (a[i] == b[i]) & ~(borrow[i-1] & (b[i-1] != a[i-1]));
        end
    endgenerate

endmodule

