module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);

wire [3:0] borrow;

assign borrow[0] = 1'b0;
assign borrow[1] = borrow[0] & (~a[1] | b[1]);
assign borrow[2] = borrow[1] & (~a[2] | b[2]);
assign borrow[3] = borrow[2] & (~a[3] | b[3]);
assign equal = ~(borrow[3] ^ borrow[2]);

endmodule

module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);

    assign out = 4'b0001 << in;

endmodule

module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);

    wire not_in1, not_in0;

    // Generate inverted inputs using NOT gates
    not(not_in1, in[1]);
    not(not_in0, in[0]);

    // Generate each output using AND gates
    and(out[0], in[0], not_in1);
    and(out[1], in[0], in[1]);
    and(out[2], not_in0, in[1]);
    and(out[3], not_in1, not_in0);

endmodule

module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);

    wire not_in1, not_in0;

    // Generate inverted inputs using NAND gates
    nand(not_in1, in[1], in[1]);
    nand(not_in0, in[0], in[0]);

    // Decode each output using NAND combinations
    wire temp0;
    nand(temp0, not_in1, not_in0);
    nand(out[0], temp0, temp0);

    wire temp1;
    nand(temp1, not_in1, in[0]);
    nand(out[1], temp1, temp1);

    wire temp2;
    nand(temp2, in[1], not_in0);
    nand(out[2], temp2, temp2);

    wire temp3;
    nand(temp3, in[1], in[0]);
    nand(out[3], temp3, temp3);

endmodule

module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);

    wire not_in1, not_in0;
    wire and0, and1, and2, and3;
    wire or0, or1;

    // Compute out[3]
    not(not_in1, in[1]);
    not(not_in0, in[0]);
    and(and0, in[1], not_in0);
    and(and1, not_in1, in[0]);
    or(or0, and0, and1);
    and(and2, or0, in[1]);
    and(and3, or0, in[0]);
    or(out[3], and2, and3);

    // Compute out[2]
    not(not_in1, in[1]);
    not(not_in0, in[0]);
    and(and0, in[1], not_in0);
    and(and1, not_in1, in[0]);
    or(or0, and0, and1);
    and(and2, or0, in[1]);
    and(and3, or0, in[0]);
    or(out[2], and2, and3);

    // Compute out[1]
    not(not_in1, in[1]);
    not(not_in0, in[0]);
    and(and0, in[1], not_in0);
    and(and1, not_in1, in[0]);
    or(or0, and0, and1);
    and(and2, or0, in[1]);
    and(and3, or0, in[0]);
    or(out[1], and2, and3);

    // Compute out[0]
    not(not_in1, in[1]);
    not(not_in0, in[0]);
    and(and0, in[1], not_in0);
    and(and1, not_in1, in[0]);
    or(or0, and0, and1);
    and(and2, or0, in[1]);
    and(and3, or0, in[0]);
    or(out[0], and2, and3);

endmodule

