module fsm_3state (
    input clk, reset,
    output [1:0] state
);
    parameter STATE_IDLE = 2'b00;
    parameter STATE_CLK High = 2'b01;
    parameter STATE_RESET = 2'b10;

    reg [1:0] state_reg, state_next;

    always @(posedge clk or posedge reset) begin
        if (reset)
            state_reg <= STATE_RESET;
        else
            state_reg <= state_next;
    end

    always @* begin
        case (state_reg)
            STATE_IDLE: state_next = STATE_CLK High;
            STATE_CLK High: state_next = STATE_IDLE;
            STATE_RESET: state_next = STATE_IDLE;
            default: state_next = STATE_IDLE;
        endcase
    end

    assign state = state_reg;
endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);
    parameter s0 = 3'b000,
              s1 = 3'b001,
              s2 = 3'b010,
              s3 = 3'b011,
              s4 = 3'b100,
              s5 = 3'b101,
              s6 = 3'b110,
              s7 = 3'b111;

    reg [2:0] current_state, next_state;

    // State register with synchronous reset
    always @(posedge clk) begin
        if (reset)
            current_state <= s0;
        else
            current_state <= next_state;
    end

    // Next state logic (example: cyclic transition s0→s1→s2→...→s7→s0)
    always @* begin
        case (current_state)
            s0: next_state = s1;
            s1: next_state = s2;
            s2: next_state = s3;
            s3: next_state = s4;
            s4: next_state = s5;
            s5: next_state = s6;
            s6: next_state = s7;
            s7: next_state = s0;
            default: next_state = s0;
        endcase
    end

    // Output assignment
    assign state = current_state[1:0];

endmodule

