module traffic_light (
    input clk, reset,
    output [2:0] light
);

reg [2:0] current_state, next_state;

parameter red = 3'b100;
parameter yellow = 3'b010;
parameter green = 3'b001;

// State register
always @(posedge clk or posedge reset) begin
    if (reset)
        current_state <= red;
    else
        current_state <= next_state;
end

// Next state logic
always @(*) begin
    case (current_state)
        red:    next_state = yellow;
        yellow: next_state = green;
        green:  next_state = red;
        default: next_state = red;
    endcase
end

assign light = current_state;

endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);

    // Define light states as one-hot encoded
    localparam GREEN  = 3'b001;
    localparam YELLOW = 3'b010;
    localparam RED    = 3'b100;

    reg [2:0] light_state;
    reg [5:0] counter;  // Counter to track time for each state (up to 62 cycles)

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            light_state <= GREEN;
            counter <= 0;
        end else begin
            if (counter == 6'd62) begin
                // Transition based on current state
                case (light_state)
                    GREEN:  light_state <= YELLOW;
                    YELLOW: light_state <= RED;
                    RED:    light_state <= GREEN;
                    default: light_state <= GREEN;
                endcase
                counter <= 0;
            end else begin
                counter <= counter + 1;
            end
        end
    end

    assign light = light_state;

endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);
    reg [2:0] light_reg;
    wire [2:0] next_light;

    // Next state logic
    assign next_light[2] = (~light_reg[2] & light_reg[1] & light_reg[0]) | (light_reg[2] & ~light_reg[1] & ~light_reg[0]);
    assign next_light[1] = (~light_reg[2] & ~light_reg[1] & light_reg[0]) | (light_reg[2] & ~light_reg[0] & light_reg[1]);
    assign next_light[0] = (~light_reg[2] & light_reg[1] & ~light_reg[0]) | (light_reg[2] & light_reg[1] & ~light_reg[0]);

    // State update with synchronous reset
    always @(posedge clk) begin
        if (reset)
            light_reg <= 3'b001;
        else
            light_reg <= next_light;
    end

    assign light = light_reg;
endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);

    parameter RED = 3'b100;
    parameter YELLOW = 3'b010;
    parameter GREEN = 3'b001;

    reg [2:0] current_state, next_state;

    always @(posedge clk or posedge reset) begin
        if (reset)
            current_state <= RED;
        else
            current_state <= next_state;
    end

    always @(*) begin
        case (current_state)
            RED:    next_state = YELLOW;
            YELLOW: next_state = GREEN;
            GREEN:  next_state = RED;
            default: next_state = RED;
        endcase
    end

    assign light = current_state;

