module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

// State definitions
localparam S_IDLE = 2'b00;
localparam S_UP   = 2'b01;
localparam S_DOWN = 2'b10;

reg [1:0] state_reg, state_next;
reg [3:0] timer;

// State register and reset logic
always @(posedge clk) begin
    if (reset)
        state_reg <= S_IDLE;
    else
        state_reg <= state_next;
end

// Next state logic
always @(*) begin
    case (state_reg)
        S_IDLE: begin
            state_next = up_request ? S_UP : 
                        down_request ? S_DOWN : S_IDLE;
        end
        S_UP:   state_next = S_IDLE;
        S_DOWN: state_next = S_IDLE;
        default: state_next = S_IDLE;
    endcase
end

// Timer logic
always @(posedge clk) begin
    if (reset)
        timer <= 4'd0;
    else begin
        if (state_reg != state_next)
            timer <= 4'd0;
        else if (state_reg == S_UP || state_reg == S_DOWN)
            timer <= timer + 1;
        else
            timer <= 4'd0;
    end
end

// Assign state output
assign state = state_reg;

endmodule

