module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

    // State definitions
    localparam [1:0] IDLE = 2'b00,
                     MOV  = 2'b01,
                     END  = 2'b10;

    reg [1:0] current_state, next_state;
    reg [2:0] timer;      // 3-bit timer for up to 4 cycles
    reg direction;        // 1'b0: up, 1'b1: down

    // Sequential state update and timer logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= IDLE;
            timer <= 0;
            direction <= 0;
        end else begin
            current_state <= next_state;
            if (current_state == MOV) begin
                if (timer == 4) begin
                    timer <= 0;
                    if (direction == 0 && up_request)
                        direction <= 1;
                    else if (direction == 1 && down_request)
                        direction <= 0;
                end else
                    timer <= timer + 1;
            end else
                timer <= 0;
        end
    end

    // Combinational next state logic
    always @(*) begin
        case (current_state)
            IDLE: begin
                if (up_request) begin
                    next_state = MOV;
                    direction = 0;
                end else if (down_request) begin
                    next_state = MOV;
                    direction = 1;
                end else begin
                    next_state = IDLE;
                    direction = 0;
                end
            end
            MOV: next_state = END;
            END: next_state = IDLE;
            default: next_state = IDLE;
        endcase
    end

    // Tri-state output for disabled resets
    assign state = reset ? state : 2'bzz;

endmodule

