    always @(posedge clk) begin
        if (reset)
            current_state <= IDLE;
        else
            current_state <= next_state;
    end

    // Counter logic
    always @(posedge clk) begin
        if (reset)
            cnt <= 3'b0;
        else if (current_state == S1) begin
            if (coin_inserted)
                cnt <= 3'b0;
            else if (item_selected)
                cnt <= cnt + 1;
        end else
            cnt <= 3'b0;
    end

    // Next state logic
    always @(*) begin
        next_state = current_state;
        case (current_state)
            IDLE: begin
                if (coin_inserted)
                    next_state = S1;
            end
            S1: begin
                if (cnt[1]) // cnt >=4 (bit[1] set)
                    next_state = S2;
                else if (item_selected)
                    next_state = S3;
            end
            S2: begin
                if (cnt[1])
                    next_state = S3;
            end
            S3: begin
                next_state = IDLE;
            end
            default: next_state = IDLE;
        endcase
    end

    assign state = current_state;

