module log2_int (
    input signed [15:0] in_0,
    output signed [7:0] out
);

wire sign = in_0[15];
wire [15:0] magnitude = sign ? (-in_0) : in_0;

reg [7:0] approx;
integer i;

always @(*) begin
    approx = 8'd0;
    for (i = 15; i >= 0; i = i - 1) begin
        if ((approx | (1 << i)) * (approx | (1 << i)) <= magnitude)
            approx = approx | (1 << i);
    end
end

assign out = {sign, approx};

endmodule

