module mult_4bit (
    input [3:0] a, b,
    output [7:0] out
);
    wire [3:0] G;
    wire [3:0] P;

    // Generate and Propagate signals using AND and OR gates
    and (G[0], a[0], b[0]);
    and (G[1], a[1], b[1]);
    and (G[2], a[2], b[2]);
    and (G[3], a[3], b[3]);

    or (P[0], a[0], b[0]);
    or (P[1], a[1], b[1]);
    or (P[2], a[2], b[2]);
    or (P[3], a[3], b[3]);

    // Carry Look-Ahead logic for each bit
    wire c1, c2, c3, c4;

    assign c1 = G[0];
    assign c2 = G[1] | (P[1] & G[0]);
    assign c3 = G[2] | (P[2] & G[1]) | (P[2] & P[1] & G[0]);
    assign c4 = G[3] | (P[3] & G[2]) | (P[3] & P[2] & G[1]) | (P[3] & P[2] & P[1] & G[0]);

    // Sum bits calculation using XOR gates
    xor (out[0], a[0], b[0]);           // out[0] = a[0] ^ b[0]
    xor (out[1], a[1], b[1], c1);     // out[1] = a[1] ^ b[1] ^ c1
    xor (out[2], a[2], b[2], c2);     // out[2] = a[2] ^ b[2] ^ c2
    xor (out[3], a[3], b[3], c3);     // out[3] = a[3] ^ b[3] ^ c3
    xor (out[4], a[0], b[0], c4);     // out[4] = a[0] ^ b[0] ^ c4 (reused for bit4)
    xor (out[5], a[1], b[1], c4);     // out[5] = a[1] ^ b[1] ^ c4
    xor (out[6], a[2], b[2], c4);     // out[6] = a[2] ^ b[2] ^ c4
    xor (out[7], a[3], b[3], c4);     // out[7] = a[3] ^ b[3] ^ c4

endmodule

