module modular_add_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);

    // Define field elements as local parameters
    localparam [7:0] 
        a = 8'h01,
        b = 8'h02,
        c = 8'h03,
        d = 8'h04,
        e = 8'h05,
        f = 8'h06,
        g = 8'h07,
        h = 8'h08;

    // Field multiplication logic
    wire [7:0] a_times_b = (a & b) ^ ((a[7] ^ b[7]) ? (a ^ b) : 8'h00);
    wire [7:0] c_times_d = (c & d) ^ ((c[7] ^ d[7]) ? (c ^ d) : 8'h00);
    wire [7:0] e_times_f = (e & f) ^ ((e[7] ^ f[7]) ? (e ^ f) : 8'h00);
    wire [7:0] g_times_h = (g & h) ^ ((g[7] ^ h[7]) ? (g ^ h) : 8'h00);

    // Polynomial evaluation
    wire [7:0] a_times_b_times_c_times_d = a_times_b ^ (c_times_d);
    wire [7:0] e_times_f_times_g_times_h = e_times_f ^ g_times_h;

    // Final multiplication
    assign data_out = a_times_b_times_c_times_d ^ e_times_f_times_g_times_h;

endmodule

