module modular_add_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);

    // Configuration constants
    localparam [3:0] 
        KEY_SIZE    = 4,
        DATA_SIZE   = 8,
        CIPHER_SIZE = 8,
        BLOCK_SIZE  = 16,
        SP_BOX_SIZE = 16;

        // Interaction constants
    localparam [15:0] 
        KEY_BOX_SIZE = 32,
        DATA_BOX_SIZE = 64,
        CIPHER_BOX_SIZE = 64;

        // Derived constants
    localparam [15:0] 
        KEY_BOX_OFFSET = 16 - KEY_BOX_SIZE,
        DATA_BOX_OFFSET = 16 - DATA_BOX_SIZE,
        CIPHER_BOX_OFFSET = 16 - CIPHER_BOX_SIZE;

    // Internal registers
    reg [KEY_SIZE-1:0] key_reg;
    reg [DATA_SIZE-1:0] data_reg;
    reg [CIPHER_SIZE-1:0] cipher_reg;

    // Main processing loop
    always @* begin
        integer i;
        for (i = 0; i < BLOCK_SIZE; i = i + 1) begin
            // Key module interaction
            key_reg[i] = 
                (i < KEY_SIZE) ? data_in[i] : 
                (i < KEY_SIZE + DATA_SIZE) ? key_reg[i - KEY_SIZE] : 
                (i < KEY_SIZE + DATA_SIZE + CIPHER_SIZE) ? (cipher_reg[i - (KEY_SIZE + DATA_SIZE)] ^ key_reg[i - KEY_SIZE]) : 
                1'b0;

            // Data module interaction
            data_reg[i] = 
                (i < DATA_SIZE) ? data_in[i] : 
                (i < DATA_SIZE + CIPHER_SIZE) ? (cipher_reg[i - DATA_SIZE] ^ data_reg[i - DATA_SIZE]) : 
                1'b0;

            // Cipher module interaction
            cipher_reg[i] = 
                (i < CIPHER_SIZE) ? (data_reg[i] ^ key_reg[i]) : 
                (i < CIPHER_SIZE + KEY_SIZE) ? (data_reg[i] ^ key_reg[i - KEY_SIZE]) : 
                (i < CIPHER_SIZE + KEY_SIZE + DATA_SIZE) ? (cipher_reg[i - (CIPHER_SIZE + KEY_SIZE)] ^ data_reg[i - CIPHER_SIZE]) : 
                1'b0;
        end
    end

    // Output assignment
    assign data_out = cipher_reg;

endmodule

module feistel_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    parameter KEY = 4'b1010; // Example key, user can override

    wire [3:0] data_in_low  = data_in[3:0];
    wire [3:0] data_in_high = data_in[7:4];
    wire [3:0] key = KEY;

    // Split data_in_high into rows (low byte is ignored)
    wire [1:0] row0 = data_in_high[3:2];
    wire [1:0] row1 = data_in_high[1:0];

    // Split key into 2x2 matrix
    wire [1:0] key_row0 = key[3:2];
    wire [1:0] key_row1 = key[1:0];

    // Function to apply XOR and permutation (example permutation: swap rows)
    function [1:0] encrypt_half;
        input [1:0] data;
        input [1:0] key_part;
        integer i;
        begin
            encrypt_half = 2'b0;
            for (i = 0; i < 2; i = i + 1) begin
                encrypt_half[i] = data[i] ^ key_part[i];
            end
        end
    endfunction

    // Process each row
    wire [1:0] row0_out = encrypt_half(row0, key_row0);
    wire [1:0] row1_out = encrypt_half(row1, key_row1);

    // Permute the results (example: swap again)
    wire [1:0] final_row0 = row1_out;
    wire [1:0] final_row1 = row0_out;

    // Concatenate to form output (low byte is ignored)
    assign data_out = {final_row0, final_row1, 4'b0};

endmodule

