    always @(posedge clk or posedge rst) begin
        if (rst) begin
            ff1 <= 1'b0;
            ff2 <= 1'b0;
        end else begin
            ff1 <= ~ff1;
            ff2 <= ff1;
        end
    end

    assign clk_out = ff2;
endmodule

module clock_div2 (
    input clk,
    input rst,
    output clk_out
);
    parameter DIVISOR = 2;

    reg [31:0] counter;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            counter <= 0;
        end else begin
            if (counter == DIVISOR - 1)
                counter <= 0;
            else
                counter <= counter + 1;
        end
    end

    assign clk_out = (counter == DIVISOR - 1);

endmodule

module clock_div2 (
    input clk,
    input rst,
    output clk_out
);
    parameter DIVISOR = 2;

    localparam WIDTH = (DIVISOR == 1) ? 1 : ($clog2(DIVISOR) - 1);
    reg [WIDTH-1:0] cnt;

    assign clk_out = (cnt == DIVISOR - 1);

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            cnt <= 0;
        end else begin
            if (cnt == DIVISOR - 1) begin
                cnt <= 0;
            end else begin
                cnt <= cnt + 1;
            end
        end
    end
endmodule

