module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);
    // Intermediate wires for bit-wise comparisons
    wire a3_xnor_b3, a2_xnor_b2, a1_xnor_b1, a0_xnor_b0;
    wire a3_gt_b3, a3_eq_b3, a2_gt_b2, a2_eq_b2, a1_gt_b1, a1_eq_b1, a0_gt_b0, a0_eq_b0;
    wire term1, term2, term3, term4;
    wire A_gt_B, A_eq_B, A_lt_B;

    // Compute each bit's comparison using XNOR and AND/OR/NOT gates
    xor g1(a3_xnor_b3, a[3], b[3]);
    not g2(a3_gt_b3, a3_xnor_b3);  // a3 > b3 (since a3 and b3 are bits)
    xor g3(a2_xnor_b2, a[2], b[2]);
    not g4(a2_gt_b2, a2_xnor_b2);
    xor g5(a1_xnor_b1, a[1], b[1]);
    not g6(a1_gt_b1, a1_xnor_b1);
    xor g7(a0_xnor_b0, a[0], b[0]);
    not g8(a0_gt_b0, a0_xnor_b0);

    // Compute A_gt_B = a3_gt_b3 | (a3_eq_b3 & a2_gt_b2) | (a3_eq_b3 & a2_eq_b2 & a1_gt_b1) | (a3_eq_b3 & a2_eq_b2 & a1_eq_b1 & a0_gt_b0)
    and g9(a3_eq_b3, a3_xnor_b3, a3_xnor_b3);  // a3_eq_b3
    and g10(a2_gt_b2_and_a3_eq, a2_gt_b2, a3_eq_b3);
    and g11(a1_gt_b1_and_a3_eq_a2, a1_gt_b1, a3_eq_b3, a2_eq_b2);
    and g12(a0_gt_b0_and_a3_eq_a2_a1, a0_gt_b0, a3_eq_b3, a2_eq_b2, a1_eq_b1);
    or g13(term1, a3_gt_b3, a2_gt_b2_and_a3_eq);
    or g14(term2, term1, a1_gt_b1_and_a3_eq_a2);
    or g15(term3, term2, a0_gt_b0_and_a3_eq_a2_a1);
    or g16(A_gt_B, term3, a3_gt_b3);  // A_gt_B calculation

    // Compute A_eq_B = a3_eq_b3 & a2_eq_b2 & a1_eq_b1 & a0_eq_b0
    and g17(a2_eq_b2_and_a3, a2_eq_b2, a3_eq_b3);
    and g18(a1_eq_b1_and_a3_a2, a1_eq_b1, a2_eq_b2_and_a3);
    and g19(a0_eq_b0_and_a3_a2_a1, a0_eq_b0, a1_eq_b1_and_a3_a2);
    and g20(A_eq_B, a0_eq_b0_and_a3_a2_a1, a3_eq_b3);

    // Compute A_lt_B = a3_eq_b3 & a2_eq_b2 & a1_gt_b1 & a0_eq_b0 | a3_eq_b3 & a2_gt_b2 & a0_eq_b0
    // Simplified as: A_lt_B = ~A_gt_B & ~A_eq_B (since A_lt_B is the remaining case)
    not g21(A_lt_B, A_gt_B);
    not g22(A_eq_B_complement, A_eq_B);
    and g23(A_lt_B_final, ~A_eq_B, A_gt_B_complement);  // A_lt_B calculation

    assign gt = A_gt_B;
    assign eq = A_eq_B;
    assign lt = A_lt_B_final;
endmodule

module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);
    wire [3:0] a_eq_b;
    wire [3:0] a_gtb_b;
    wire [3:0] a_ltb_b;
    wire gt, eq_bit, lt;

    // Generate equality bits (XNOR)
    xor(xor1, a[0], b[0]);
    not(a_eq_b[0], xor1);
    repeat(3:1) begin
        xor(xor_i, a[i], b[i]);
        not(a_eq_b[i], xor_i);
    end

    // Generate a > b bits (AND of a[i] & ~b[i])
    nand(nand1, a[0], b[0]);
    not(a_gtb_b[0], nand1);
    repeat(3:1) begin
        nand(nand_i, a[i], b[i]);
        not(a_gtb_b[i], nand_i);
    end

    // Generate a < b bits (NAND of a[i] & ~b[i])
    nand(nand2, a[0], b[0]);
    not(a_ltb_b[0], nand2);
    repeat(3:1) begin
        nand(nand_ltb, a[i], b[i]);
        not(a_ltb_b[i], nand_ltb);
    end

    // Compute overall gt and eq signals
    and(gt_temp, a_gtb_b[3], a_gtb_b[2], a_gtb_b[1], a_gtb_b[0]);
    and(eq_bit_temp, a_eq_b[3], a_eq_b[2], a_eq_b[1], a_eq_b[0]);
    not(eq_bit, eq_bit_temp);

    // Compute lt signal
    or(lt_temp, a_ltb_b[3], a_ltb_b[2], a_ltb_b[1], a_ltb_b[0]);
    assign lt = lt_temp;

    // Assign outputs
    assign gt = gt_temp;
    assign eq = eq_bit;
    assign lt = lt_temp;

endmodule

module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);

    // Generate inversion signals for each input bit
    wire [3:0] a_n;
    wire [3:0] b_n;
    generate
        genvar i;
        for (i = 0; i < 4; i = i + 1) begin : inv_gen
            not(a_n[i], a[i]);
            not(b_n[i], b[i]);
        end
    endgenerate

    // Compute gt (a > b) using AND and OR gates
    wire [3:0] gt_and;
    assign gt_and[0] = a[0] & b_n[0];
    assign gt_and[1] = a[1] & b_n[1];
    assign gt_and[2] = a[2] & b_n[2];
    assign gt_and[3] = a[3] & b_n[3];

    wire [3:0] gt_or;
    assign gt_or[0] = gt_and[0];
    assign gt_or[1] = gt_and[1] | gt_or[0];
    assign gt_or[2] = gt_and[2] | gt_or[1];
    assign gt_or[3] = gt_and[3] | gt_or[2];
    assign gt = gt_or[3];

    // Compute eq (a == b) using XNOR gates
    xnor(eq[0], a[0], b[0]);
    xnor(eq[1], a[1], b[1]);
    xnor(eq[2], a[2], b[2]);
    xnor(eq[3], a[3], b[3]);
    and(eq, eq[0], eq[1], eq[2], eq[3]);

    // Compute lt (a < b) using NAND and OR gates
    wire [3:0] lt_nand;
    assign lt_nand[0] = ~(a[0] & b[0]);
    assign lt_nand[1] = ~(a[1] & b[1]);
    assign lt_nand[2] = ~(a[2] & b[2]);
    assign lt_nand[3] = ~(a[3] & b[3]);

    wire [3:0] lt_or;
    assign lt_or[0] = lt_nand[0];
    assign lt_or[1] = lt_nand[1] | lt_or[0];
    assign lt_or[2] = lt_nand[2] | lt_or[1];
    assign lt_or[3] = lt_nand[3] | lt_or[2];
    assign lt = lt_or[3];

endmodule

module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);
