    wire a3_xor_b3, a2_xor_b2, a1_xor_b1, a0_xor_b0;
    wire a_less_than_b, a_eq_b;

    // Determine if a and b are the same (using XNOR)
    xnor (a_eq_b, a[3], b[3]);
    xnor (a_eq_b2, a[2], b[2]);
    xnor (a_eq_b3, a[1], b[1]);
    xnor (a_eq_b4, a[0], b[0]);
    and (eq, a_eq_b, a_eq_b2, a_eq_b3, a_eq_b4);

