    parameter IBUF_LOW_PWR = "TRUE";
    parameter IOSTANDARD = "DEFAULT";

    // Configuration constants
    localparam DEFSRCH = 1;

    // Utility macros for buffer control
    `ifdef DIFF_TERM
        // Differential buffer configuration
        assign out0 = $(buf_if (in, sel, DEFSRCH));
        assign out1 = $(buf_if (-in, sel, DEFSRCH));
    `else
        // Single-ended buffer configuration
        assign out0 = $(buf_if (in, sel, DEFSRCH));
    $endif

