    macro buf_if (input_signal, enable, defsrch)
        if (enable) begin
            // Differential pair with input scaling
            assign input_signal = $signed(input_signal) * 2;
        end else begin
            // Buffered output with optional differential pairing
            assign input_signal = $signed(input_signal);
