  parameter RST = 2'b00;
  parameter S0 = 2'b01;
  parameter S1 = 2'b10;

  // State register with asynchronous reset
  always @(posedge clk or posedge enable) begin
    if (enable) state <= RST;
    else state <= next_state;
  end

  // Next state logic
  always @* begin
    if (enable) next_state = RST;
    else begin
      case (state)
        RST: next_state = (S == 0) ? S0 : RST;
        S0: next_state = (S == 1) ? S1 : S0;
        S1: begin
          if (S == 0) next_state = S0;
          else if (A || B || C) next_state = RST;
          else next_state = S1;
        end
        default: next_state = RST;
      endcase
    end
  end

  // Output logic
  always @* begin
    Z = (state == S1) && (A || B || C);
  end

