  reg prev_C;
  wire [1:0] curr_AB = {A, B};

  always @(posedge clk or negedge enable) begin
    if (!enable) begin
      prev_AB <= 2'b00;
      prev_C <= 1'b0;
      Z <= 1'b0;
    end else begin
      // Capture previous values of A, B, and C
      prev_AB <= curr_AB;
      prev_C <= C;

      // Check for valid transitions and update Z
      if ((curr_AB != prev_AB) && (curr_AB != 2'b00)) begin
        // Check left or right movement and ensure C didn't change
        if ((curr_AB == 2'b01 && prev_AB == 2'b10) || 
            (curr_AB == 2'b10 && prev_AB == 2'b01)) begin
          Z <= (C == prev_C) ? 1'b1 : 1'b0;
        end
      end
    end
  end

