module TopModule (
  input clk,
  input aresetn,
  input x,
  output reg z
);

  parameter DEBOUNCE_COUNT = 20000; // Adjust based on clock frequency

  // States
  reg [1:0] state;
  localparam S_IDLE     = 2'b00,
             S_DEBOUNCE = 2'b01,
             S_TRIGGER  = 2'b10;

  // counters
  reg [31:0] counter;

  always @(posedge clk or negedge aresetn) begin
    if (!aresetn) begin
      state <= S_IDLE;
      counter <= 0;
      z <= 0;
    end else begin
      case (state)
        S_IDLE: begin
          z <= 0;
          if (x) begin
            state <= S_DEBOUNCE;
            counter <= 0;
          end
        end

        S_DEBOUNCE: begin
          if (x) begin
            counter <= counter + 1;
            if (counter >= DEBOUNCE_COUNT) begin
              state <= S_TRIGGER;
              counter <= 0;
            end
          end else begin
            counter <= 0;
          end
        end

        S_TRIGGER: begin
          z <= 1;
          if (!x) begin
            state <= S_IDLE;
          end
        end

        default: state <= S_IDLE;
      endcase
    end
  end

endmodule

