module TopModule (
  input clk,
  input [7:0] in,
  output reg [7:0] pedge
);

  // State definitions
  localparam [1:0]
    IDLE = 2'b00,
    SHIFT = 2'b01,
    DONE = 2'b10;

  reg [1:0] state;
  reg [7:0] counter;
  reg [7:0] temp_q;

  always @(posedge clk) begin
    case (state)
      IDLE: begin
        pedge <= in;
        counter <= 8'd1;
        state <= SHIFT;
      end
      SHIFT: begin
        // Compute feedback based on current mask
        temp_q = (in ^ (in & mask)) << 1;
        if (counter == 8'd127)
          state <= DONE;
        else
          state <= SHIFT;
        counter <= counter + 8'd1;
      end
      DONE: begin
        state <= IDLE;
      end
      default: state <= IDLE;
    endcase
  end

  // Mask is derived from the current state during SHIFT
  wire [7:0] mask = (counter << 1) | ((counter << 1) - 8'd1);

  initial begin
    state = IDLE;
    counter = 8'd1;
  end

