module TopModule (
  input a,
  input b,
  input cin,
  output cout,
  output sum
);

  wire carry1, carry2, carry3, carry4, carry5, carry6, carry7, carry8, carry9;

  // Half Adder for bit 0 (2 gates)
  xor(sum[0], a[0], b[0]);
  and(carry1, a[0], b[0]);

  // Full Adders for bits 1-7 (5 gates each)
  // Bit 1
  xor(sum[1], a[1], b[1]);
  and(carry2, a[1], b[1]);
  and(carry3, a[1], carry1);
  and(carry4, b[1], carry1);
  or(sum[1], carry3, carry4);

  // Bit 2
  xor(sum[2], a[2], b[2]);
  and(carry5, a[2], b[2]);
  and(carry6, a[2], carry2);
  and(carry7, b[2], carry2);
  or(sum[2], carry6, carry7);

  // Bit 3
  xor(sum[3], a[3], b[3]);
  and(carry8, a[3], b[3]);
  and(carry9, a[3], carry5);
  and(carry10, b[3], carry5);
  or(sum[3], carry9, carry10);

  // Bit 4
  xor(sum[4], a[4], b[4]);
  and(carry11, a[4], b[4]);
  and(carry12, a[4], carry8);
  and(carry13, b[4], carry8);
  or(sum[4], carry12, carry13);

  // Bit 5
  xor(sum[5], a[5], b[5]);
  and(carry14, a[5], b[5]);
  and(carry15, a[5], carry11);
  and(carry16, b[5], carry11);
  or(sum[5], carry15, carry16);

  // Bit 6
  xor(sum[6], a[6], b[6]);
  and(carry17, a[6], b[6]);
  and(carry18, a[6], carry14);
  and(carry19, b[6], carry14);
  or(sum[6], carry18, carry19);

  // Bit 7
  xor(sum[7], a[7], b[7]);
  and(carry20, a[7], b[7]);
  and(carry21, a[7], carry17);
  and(carry22, b[7], carry17);
  or(sum[7], carry21, carry22);

  // Carry-out for each bit
  assign cout[0] = carry1;
  assign cout[1] = carry2;
  assign cout[2] = carry3;
  assign cout[3] = carry4;
  assign cout[4] = carry5;
  assign cout[5] = carry6;
  assign cout[6] = carry7;
  assign cout[7] = carry8;
  assign cout[8] = carry9;

endmodule

