module TopModule (
  input clk,
  input j,
  input k,
  input reset,
  output out
);

  parameter READY = 2'b00;
  parameter WAIT = 2'b01;
  parameter WRITING = 2'b10;
  parameter WRITEDONEMARK = 2'b11;

  reg [1:0] state, next_state;
  reg [2:0] counter;
  reg out_reg;

  // State register
  always @(posedge clk) begin
    if (reset)
      state <= READY;
    else
      state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (state)
      READY: next_state = j ? WAIT : READY;
      WAIT: next_state = j ? WRITING : READY;
      WRITING: next_state = (counter == 3'd4) ? WRITEDONEMARK : WRITING;
      WRITEDONEMARK: next_state = (!j) ? READY : WRITEDONEMARK;
      default: next_state = READY;
    endcase
  end

  // Counter logic
  always @(posedge clk) begin
    if (reset)
      counter <= 3'd0;
    else case (state)
      WRITING: counter <= counter + 1;
      default: counter <= 3'd0;
    endcase
  end

  // Write acknowledge logic
  always @(posedge clk) begin
    if (reset)
      out_reg <= 1'b0;
    else if (state == WRITEDONEMARK && !j)
      out_reg <= 1'b1;
    else
      out_reg <= 1'b0;
  end

  assign out = out_reg;

endmodule

