  assign next_state[2] = (k & state[1]) | (j & state[2]) | (reset & ~state[0]);

  // State register with synchronous reset
  always @(posedge clk) begin
    if (reset)
      state <= 3'b000;
    else
      state <= next_state;
  end

  // Output logic
  assign out = state[2] ^ state[0];

