  always @(posedge clk or posedge areset) begin
    if (areset)
      current_state <= INIT;
    else
      current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      INIT: next_state = load ? LOAD : INIT;
      LOAD: next_state = ena ? INIT : LOAD;
      default: next_state = INIT;
    endcase
  end

  // Data register with asynchronous reset and load control
  always @(posedge clk or posedge areset) begin
    if (areset)
      q <= 4'b0;
    else if (current_state == LOAD && load)
      q <= data;
  end

