  wire [7:0] dividend_reg_lo = dividend_reg[7:0];
  wire [8:0] temp_remainder_hi = {remainder_reg, dividend_reg_hi};
  wire [7:0] subtraction_result = temp_remainder_hi - 8'h01;

  always @* begin
    if (counter == 5'd0) begin
      quotient_reg = 8'hFF;
      remainder_reg = 8'h00;
      dividend_reg = in;
      counter = 5'd1;
    end else if (counter <= 5'd16) begin
      if (subtraction_result[7] == 1'b0) begin
        quotient_reg = {quotient_reg[6:0], 1'b1};
        remainder_reg = subtraction_result;
      end else begin
        quotient_reg = {quotient_reg[6:0], 1'b0};
        remainder_reg = remainder_reg;
      end
      dividend_reg = {dividend_reg_lo, dividend_reg_hi};
      counter = counter - 1;
    end
  end

  assign out_hi = quotient_reg;
  assign out_lo = remainder_reg;

endmodule

