  parameter s0 = 1'b0;
  parameter s1 = 1'b1;

  reg current_state;
  reg next_state;

  // State register with synchronous reset
  always @(posedge clk) begin
    if (reset)
      current_state <= INIT;
    else
      current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      INIT: next_state = w ? s1 : s0;
      s0:   next_state = w ? s1 : s0;
      s1:   next_state = w ? s1 : s0;
      default: next_state = INIT;
    endcase
  end

  // Output logic
  assign z = (current_state == s1);

