module TopModule (
  input clk,
  input x,
  input [2:0] y,
  output reg Y0,
  output reg z
);

  reg [2:0] w, x, y;

  always @(posedge clk) begin
    // Compute syndrome bits
    wire s1 = x[0] ^ y[0] ^ w[0] ^ x[1];
    wire s2 = x[1] ^ y[1] ^ w[1] ^ x[2];
    wire s3 = x[2] ^ y[2] ^ w[2] ^ x[0];

    // Syndrome is {s3, s2, s1}
    wire [2:0] syndrome = {s3, s2, s1};

    // Determine if correction is needed and which bit to flip
    if (syndrome != 0) begin
      case (syndrome)
        3'b100: begin // Error in x[0]
          y[0] <= ~y[0];
          z <= 1;
        end
        3'b010: begin // Error in x[1]
          y[1] <= ~y[1];
          z <= 1;
        end
        3'b001: begin // Error in x[2]
          y[2] <= ~y[2];
          z <= 1;
        end
        default: begin // No single error, z remains 0
          z <= 0;
        end
      endcase
    end else begin
      z <= 0;
    end
  end

  // Y0 is the XOR of all bits in x (parity check)
  always @(*) begin
    Y0 = x[0] ^ x[1] ^ x[2];
  end

endmodule

module TopModule (
  input clk,
