        else if (y == 3'b010) next_state = s4;
        else                 next_state = s1;
      end
      s2: begin
        if (y == 3'b011)      next_state = s3;
        else if (y == 3'b100) next_state = s4;
        else                 next_state = s2;
      end
      s3:                    next_state = s3;
      s4:                    next_state = s4;
      default:               next_state = s0;
    endcase
  end

  // Output logic
  always @* begin
    Y0 = (current_state == s3);
