module TopModule (
  input clk,
  input x,
  input [2:0] y,
  output reg Y0,
  output reg z
);

  parameter DEBOUNCE_CYCLES = 10000; // Adjust based on clock frequency

  // FSM states
  localparam STATE_UNCHANGED = 2'b00;
  localparam STATE_DEBOUNCE = 2'b01;
  localparam STATE_CHANGED = 2'b10;

  reg [1:0] state, next_state;
  reg [31:0] counter;
  reg prev_x;

  // Store previous x value for change detection
  always @(posedge clk) begin
    prev_x <= x;
  end

  // State register and counter
  always @(posedge clk) begin
    state <= next_state;
    if (state == STATE_DEBOUNCE)
      counter <= counter + 1;
    else
      counter <= 0;
  end

  // Next state logic
  always @(*) begin
    case (state)
      STATE_UNCHANGED: begin
        if (x != prev_x) begin
          next_state = STATE_CHANGED;
        end else begin
          next_state = STATE_UNCHANGED;
        end
      end
      STATE_CHANGED: begin
        if (x != prev_x) begin
          next_state = STATE_CHANGED;
        end else begin
          next_state = STATE_DEBOUNCE;
        end
      end
      STATE_DEBOUNCE: begin
        if (counter >= DEBOUNCE_CYCLES) begin
          next_state = (x != prev_x) ? STATE_CHANGED : STATE_UNCHANGED;
        end else begin
          next_state = STATE_DEBOUNCE;
        end
      end
      default: next_state = STATE_UNCHANGED;
    endcase
  end

  // Output logic
  always @(posedge clk) begin
    Y0 <= (state == STATE_CHANGED) ? 1'b1 : 1'b0;
    z <= (state == STATE_CHANGED) ? 1'b1 : 1'b0;
  end

endmodule

