  // Debounce logic for right button
  always @(posedge clk or posedge areset) begin
    if (areset) begin
      debounce_counter_right <= 0;
      right_button_debounced <= 0;
    end else begin
      if (right_button_sync2 != right_button_debounced) begin
        debounce_counter_right <= 0;
      end else if (debounce_counter_right == DEBOUNCE_COUNT) begin
        right_button_debounced <= right_button_sync2;
      end
    end
  end

  // Edge detection for button presses
  always @(posedge clk or posedge areset) begin
    if (areset) begin
      left_button_prev <= 0;
      right_button_prev <= 0;
    end else begin
      left_button_prev <= left_button_debounced;
      right_button_prev <= right_button_debounced;
    end
  end

  assign walk_left = left_button_debounced && !left_button_prev;
  assign walk_right = right_button_debounced && !right_button_prev;

