  // Synchronize data input using two flip-flops
  always @(posedge clk) begin
    if (reset) begin
      sync1 <= 1'b0;
      sync2 <= 1'b0;
    end else begin
      sync1 <= data;
      sync2 <= sync1;
    end
  end

  // Track previous synchronized value for edge detection
  always @(posedge clk) begin
    if (reset)
      prev_sync <= 1'b0;
    else
      prev_sync <= sync2;
  end

  // Counter logic with reset and edge-driven increment
  always @(posedge clk) begin
    if (reset)
      count <= 3'b0;
    else if (edge_detected)
      count <= count + 1;
  end

  // Output is high when counter is non-zero
  assign start_shifting = (count != 3'b0);

