  input [9:0] state, // 10-bit one-hot current state
  output B3_next,
  output S_next,
  output S1_next,
  output Count_next,
  output Wait_next,
  output done,
  output counting,
  output shift_ena
);

// State encoding (one-hot) assumptions:
// STATE_START:  10'b0000000001
// STATE_SHIFT_1: 10'b0000000010
// STATE_ADD:     10'b0000000100
// STATE_SUB:     10'b0000001000
// STATE_DONE:    10'b0000010000
// STATE_ERROR:   10'b0000100000

reg next_state;
reg next_B3, next_S, next_S1, next_Count, next_Wait, next_shift;
wire next_done, next_counting;

// Next state logic (combinational)
always @(*) begin
  case (state)
    10'b0000000001: // START
      next_state = done_counting ? 10'b0000000010 : 10'b0000000001; // Shift if done_counting, else stay
    10'b0000000010: // SHIFT_1
      next_state = ack ? 10'b0000000100 : 10'b0000000010; // To ADD if ack, else shift
    10'b0000000100: // ADD
      next_state = ack ? 10'b0000000010 : 10'b0000000100; // To Shift if ack, else stay
    10'b0000001000: // SUB
      next_state = ack ? 10'b0000000010 : 10'b0000001000; // To Shift if ack, else stay
    10'b0000010000: // DONE
      next_state = 10'b0000000001; // To START
    10'b0000100000: // ERROR
      next_state = 10'b0000000001; // To START
    default:
      next_state = 10'b0000000001; // Default to START
  endcase
end

// Output logic (combinational)
assign B3_next = (state == 10'b0000000001) & done_counting;
assign S_next = (state == 10'b0000000010);
assign S1_next = (state == 10'b0000000100);
assign Count_next = (state == 10'b0000001000);
assign Wait_next = (state == 10'b0000010000);
assign done = (state == 10'b0000010000);
assign counting = (state == 10'b0000000010) | (state == 10'b0000000100) | (state == 10'b0000001000);
assign shift_ena = (state == 10'b0000000010);

endmodule

