module counter_12 
(
  input rst_n,
  input clk,
  input valid_count,

  output reg [3:0] out
);

  // State definitions
  parameter INIT   = 4'b0000;
  parameter NO_OP  = 4'b0001;
  parameter WRITE  = 4'b0010;
  parameter WR_ERR = 4'b0011;
  parameter READ   = 4'b0100;
  parameter RD_ERR = 4'b0101;

  reg [3:0] current_state, next_state;

  // State register
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
      current_state <= INIT;
    else
      current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      INIT: begin
        next_state = valid_count ? WRITE : NO_OP;
      end
      NO_OP: begin
        next_state = valid_count ? WRITE : NO_OP;
      end
      WRITE: begin
        next_state = valid_count ? WRITE : RD_ERR;
      end
      WR_ERR: begin
        next_state = valid_count ? WRITE : NO_OP;
      end
      READ: begin
        next_state = valid_count ? WRITE : RD_ERR;
      end
      RD_ERR: begin
        next_state = valid_count ? WRITE : NO_OP;
      end
      default: next_state = INIT;
    endcase
  end

  // Output logic
  always @(*) begin
    out = current_state;
  end

endmodule

