module right_shifter(clk, q,d);  
    input  clk;  
    input d;  
    output  [7:0] q;  

    wire reset_n;  
    nor (reset_n, d, d);  // Generate active-low reset  

    reg [7:0] Q;  
    wire [7:0] D;  
    wire [7:0] inverted_data;  
    wire [7:0] enabled_data;  

    // Invert input data for each bit  
    generate  
        genvar i;  
        for (i=0; i<8; i=i+1) begin : invertor  
            not (inverted_data[i], d[i]);  // Assuming d is split into 8 bits  
        end  
    endgenerate  

    // Apply enable (AND) and reset (OR with inverted reset_n)  
    wire [7:0] and_out;  
    wire [7:0] or_out;  
    generate  
        for (i=0; i<8; i=i+1) begin : enable_reset  
            and (and_out[i], inverted_data[i], clk);  
            or  (or_out[i], and_out[i], reset_n);  
            assign enabled_data[i] = or_out[i];  
        end  
    endgenerate  

    // D flip-flop with gated clock  
    reg [7:0] Q_reg;  
    generate  
        for (i=0; i<8; i=i+1) begin : flip_flop  
            always @(posedge clk or posedge reset_n) begin  
                if (reset_n)  
                    Q_reg[i] <= 1'b0;  
                else  
                    Q_reg[i] <= enabled_data[i];  
            end  
        end  
    endgenerate  

    assign q = Q_reg;  

endmodule

