module right_shifter(clk, q,d);  
    input  clk;  
    input d;  
    output  [7:0] q;  

    wire [7:0] t;  

    assign t[0] = d;  
    assign q[0] = clk ? t[0] : 1'b0;  
    genvar j;  
    generate  
        for (j = 1; j < 8; j = j + 1) begin : gen_shifter  
            assign t[j] = clk ? t[j-1] : 1'b0;  
            assign q[j] = clk ? t[j] : 1'b0;  
        end  
    endgenerate  

endmodule

