module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

    // Synchronize data_en to clk_a domain
    reg [1:0] sync_sel_a;
    always @(posedge clk_a or negedge arstn) begin
        if (!arstn) begin
            sync_sel_a <= 2'b0;
        end else begin
            sync_sel_a <= {sync_sel_a[0], data_en};
        end
    end

    // Synchronize data_en to clk_b domain
    reg [1:0] sync_sel_b;
    always @(posedge clk_b or negedge brstn) begin
        if (!brstn) begin
            sync_sel_b <= 2'b0;
        end else begin
            sync_sel_b <= {sync_sel_b[0], data_en};
        end
    end

    // Select data based on synchronized enable
    wire [3:0] data_sel = sync_sel_a[1] ? data_in : 4'b0;
    wire [3:0] data_b = sync_sel_b[1] ? data_in : 4'b0;

    // Register output on clk_a with async reset
    always @(posedge clk_a or negedge arstn) begin
        if (!arstn) begin
            dataout <= 4'b0;
        end else begin
            dataout <= data_sel;
        end
    end

    // Update output on clk_b without reset
    always @(posedge clk_b) begin
        if (brstn) begin
            dataout <= data_b;
        end
    end

endmodule

module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

    // Synchronize data_en to clk_a domain with a two-stage FF and detect stable enable
    reg [2:0] sync_a;
    always @(posedge clk_a or negedge arstn) begin
        if (!arstn) sync_a <= 3'b0;
        else        sync_a <= {sync_a[1:0], data_en};
    end
    wire data_en_sync = sync_a[2];

    // Synchronize data_en to clk_b domain with a two-stage FF and detect stable enable
    reg [2:0] sync_b;
    always @(posedge clk_b or negedge brstn) begin
        if (!brstn) sync_b <= 3'b0;
        else        sync_b <= {sync_b[1:0], data_en};
    end
    wire data_en_sync_b = sync_b[2];

    // Update dataout on clk_a during valid transfers (data_en_sync is high)
    always @(posedge clk_a or negedge arstn) begin
        if (!arstn) begin
            dataout <= 4'b0;
        end else if (data_en_sync) begin
            dataout <= data_in;
        end
    end

endmodule

module synchronizer(
