		}
	end
	assign data_b = sync_b[3:0];

	// Register output in clk_a domain when enable_a is high
	always @(posedge clk_a or negedge arstn) begin
		if (!arstn) begin
			dataout <= 4'b0;
		} else begin
			if (enable_a) begin
				dataout <= data_b;
			}
		end
	end

