        if (!arstn) begin
            dataout <= 4'b0;
        end else if (enable_sync) begin
            dataout <= sync_data_a;
        end
    end

endmodule

module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;

reg [1:0] current_state, next_state;

parameter s0 = 2'b00,
          s1 = 2'b01,
          s2 = 2'b10;

// State register
always @(posedge CLK or posedge RST) begin
    if (RST)
        current_state <= s0;
    else
        current_state <= next_state;
end

// Next state logic
always @(*) begin
    case (current_state)
        s0: next_state = IN ? s1 : s0;
        s1: next_state = IN ? s1 : s2;
        s2: next_state = IN ? s1 : s0;
        default: next_state = s0;
    endcase
end

// Output logic
always @(*) begin
    MATCH = (current_state == s2) && (IN == 0);
end

endmodule

module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;

parameter [2:0] s0 = 3'b000,
                s1 = 3'b001,
                s2 = 3'b010,
                s3 = 3'b011,
                s4 = 3'b100,
                s5 = 3'b101,
                s6 = 3'b110,
                s7 = 3'b111;

reg [2:0] current_state, next_state;

always @(posedge CLK or negedge RST) begin
    if (!RST)
        current_state <= s0;
    else
        current_state <= next_state;
end

always @(*) begin
    case (current_state)
        s0: next_state = IN ? s1 : s4;
        s1: next_state = IN ? s2 : s7;
        s2: next_state = IN ? s3 : s5;
        s3: next_state = s0;
        s4: next_state = s5;
        s5: next_state = s0;
        s6: next_state = s6;
        s7: next_state = s7;
        default: next_state = s0;
    endcase
end

always @(*) begin
    MATCH = (current_state == s3) || (current_state == s6);
end

endmodule

module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;

// Define states
reg [1:0] state, next_state;
parameter S0 = 2'b00,
          S1 = 2'b01,
          S2 = 2'b10;

// State transition and reset logic
always @(posedge CLK or posedge RST) begin
    if (RST) begin
        state <= S0;
    end else begin
        state <= next_state;
    end
end

// Next state logic based on current state and IN
always @(*) begin
    case (state)
        S0: next_state = IN ? S1 : S0;
        S1: next_state = IN ? S2 : S0;
        S2: next_state = IN ? S2 : S0;
        default: next_state = S0;
    endcase
end

// Output logic: MATCH is high only in state S1
always @(*) begin
    MATCH = (state == S1) ? 1'b1 : 1'b0;
end

endmodule

module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;

reg [1:0] state, next_state;

localparam S0 = 2'b00,
           S1 = 2'b01,
           S2 = 2'b10;

always @(posedge CLK or posedge RST) begin
if (RST) state <= S0;
else state <= next_state;
end

always @(*) begin
next_state = state;
MATCH = 0;
case (state)
S0: begin
if (IN) begin
next_state = S2;
MATCH = 1;
end else next_state = S1;
end
S1: begin
if (!IN) next_state = S0;
else next_state = S2;
end
S2: begin
if (IN) next_state = S2;
else next_state = S1;
end
default: next_state = S0;
endcase
end

endmodule

module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;

reg [2:0] current_state, next_state;

// State register with asynchronous reset
always @(posedge CLK or posedge RST) begin
    if (RST)
        current_state <= 3'b000;
    else
        current_state <= next_state;
end

// Next state logic (combinational)
always @(*) begin
    case (current_state)
        3'b000: next_state = IN ? 3'b000 : 3'b001;
        3'b001: next_state = IN ? 3'b010 : 3'b000;
        3'b010: next_state = IN ? 3'b011 : 3'b001;
        3'b011: next_state = IN ? 3'b100 : 3'b010;
        3'b100: next_state = IN ? 3'b100 : 3'b011;
        default: next_state = 3'b000;
    endcase
end

// Output logic (combinational)
always @(*) begin
    MATCH = (current_state == 3'b100);
end

endmodule

module parallel2serial(
