    if (!rst_n) begin
        shift_reg <= 4'b0;
        valid_reg <= 1'b1;
    end else begin
        if (valid_reg) begin
            shift_reg <= d;
            valid_reg <= 1'b0;
        end else begin
            shift_reg <= {shift_reg[2:0], 1'b0};
        end
    end
